<script setup>
import { computed, onMounted, ref } from 'vue'
import { api } from '../api'
import { initials } from '../utils'
import { useUI } from '../stores/ui'
import Modal from '../components/Modal.vue'
import ConfirmDialog from '../components/ConfirmDialog.vue'
const ui = useUI(), teachers = ref([]), loading = ref(true), error = ref(''), search = ref(''), creating = ref(false), busy = ref(false), formError = ref(''), credentials = ref(null), confirmation = ref(null)
const name = ref(''), username = ref(''), password = ref(''), copied = ref(false)
const filtered = computed(() => teachers.value.filter(t => `${t.name} ${t.username}`.toLowerCase().includes(search.value.toLowerCase())))
async function load() { error.value = ''; try { teachers.value = await api('/teachers') } catch (e) { error.value = e.message } finally { loading.value = false } }
onMounted(load)
function openCreate() { name.value = ''; username.value = ''; password.value = ''; formError.value = ''; creating.value = true }
async function create() {
  busy.value = true; formError.value = ''
  try {
    credentials.value = await api('/teachers', { method: 'POST', body: { name: name.value, username: username.value, password: password.value || null } })
    creating.value = false; copied.value = false; await load()
  } catch (e) { formError.value = e.message } finally { busy.value = false }
}
async function confirm(done) {
  try {
    const { type, teacher } = confirmation.value
    if (type === 'reset') { credentials.value = await api(`/teachers/${teacher.id}/reset-password`, { method: 'POST' }); copied.value = false }
    else { await api(`/teachers/${teacher.id}`, { method: 'DELETE' }); await load(); ui.notify('Аккаунт преподавателя удалён') }
    confirmation.value = null
  } catch (e) { ui.notify(e.message, 'error') } finally { done() }
}
async function copy() {
  try { await navigator.clipboard.writeText(`Логин: ${credentials.value.username}\nПароль: ${credentials.value.password}`); copied.value = true }
  catch { ui.notify('Не удалось скопировать автоматически. Выделите и скопируйте данные вручную.', 'error') }
}
</script>
<template>
  <section><div class="page-heading"><div><h1>Преподаватели<span class="text-sky-600">.</span></h1></div><button class="btn primary" @click="openCreate"><Icon name="Plus" :size="17" />Добавить преподавателя</button></div><div class="teacher-access-banner"><span><Icon name="ShieldCheck" :size="21" /></span><div><strong>Раздел администратора</strong><p>Каждый преподаватель видит только свои материалы и учебные профили.</p></div><span class="badge">Закрытый доступ</span></div><div class="section-heading"><h2>Аккаунты<span class="count-badge">{{ teachers.length }}</span></h2><div class="search-field"><Icon name="Search" :size="15" /><input v-model="search" placeholder="Имя или логин…" aria-label="Поиск преподавателей" /></div></div><div v-if="error" class="error-box mb-4">{{ error }} <button class="underline" @click="load">Повторить</button></div><div v-if="loading" class="loading"><Icon name="LoaderCircle" class="spin" />Загружаем аккаунты…</div><div v-else class="teachers-table card"><div class="teacher-table-header"><span>Преподаватель</span><span>Роль</span><span>Управление</span></div><article v-for="teacher in filtered" :key="teacher.id" class="teacher-row"><div class="teacher-identity"><div class="avatar">{{ initials(teacher.name) }}</div><div><h3>{{ teacher.name }}</h3><p>@{{ teacher.username }}</p></div></div><span class="teacher-role badge" :class="teacher.role === 'admin' ? '' : 'neutral'"><Icon v-if="teacher.role === 'admin'" name="ShieldCheck" :size="11" />{{ teacher.role === 'admin' ? 'Администратор' : 'Преподаватель' }}</span><div class="teacher-actions"><span v-if="teacher.role === 'admin'" class="system-account">Системный аккаунт</span><template v-else><button class="btn secondary sm" @click="confirmation = { type: 'reset', teacher }"><Icon name="KeyRound" :size="13" />Сбросить пароль</button><button class="icon-btn red" :aria-label="`Удалить ${teacher.name}`" @click="confirmation = { type: 'delete', teacher }"><Icon name="Trash2" :size="16" /></button></template></div></article><p v-if="!filtered.length" class="text-center text-xs muted p-10">По вашему запросу ничего не найдено.</p></div><div class="info-banner"><Icon name="LockKeyhole" :size="17" /><p>Передавайте учётные данные лично. При сбросе пароля все активные сессии преподавателя будут завершены. Удаление аккаунта также удалит его материалы и профили.</p></div></section>
  <Modal v-if="creating" title="Новый преподаватель" subtitle="Пригласите коллегу в uTutor" @close="!busy && (creating = false)"><form @submit.prevent="create"><div class="modal-body"><div class="field"><label for="teacher-name">Имя преподавателя</label><input id="teacher-name" v-model="name" class="input" placeholder="Например, Анна Петрова" required maxlength="120" autofocus /></div><div class="field"><label for="teacher-login">Логин</label><input id="teacher-login" v-model="username" class="input" placeholder="anna.petrova" required minlength="3" maxlength="64" pattern="[a-zA-Z0-9_.\-]+" autocomplete="off" /><span class="muted text-[10px]">Латинские буквы, цифры, точка, дефис или подчёркивание</span></div><div class="field"><label for="teacher-password">Пароль <span class="muted font-normal">· необязательно</span></label><input id="teacher-password" v-model="password" class="input" type="password" placeholder="Оставьте пустым для генерации" minlength="10" maxlength="128" autocomplete="new-password" /><span class="muted text-[10px]">Не менее 10 символов. Случайный пароль будет показан после создания.</span></div><div v-if="formError" class="error-box mt-4">{{ formError }}</div></div><footer class="modal-footer"><button type="button" class="btn secondary" :disabled="busy" @click="creating = false">Отмена</button><button class="btn primary" :disabled="busy || !name.trim() || !username"><Icon :name="busy ? 'LoaderCircle' : 'Plus'" :class="{ spin: busy }" :size="16" />Создать аккаунт</button></footer></form></Modal>
  <Modal v-if="credentials" title="Доступ готов" subtitle="Сохраните данные и передайте их преподавателю" @close="credentials = null"><div class="modal-body"><div class="credentials-info"><Icon name="CircleCheck" :size="23" /><p>Пароль показывается только сейчас.<br />После закрытия восстановить его нельзя — только сбросить.</p></div><div class="credential-line"><span>Логин</span><code>{{ credentials.username }}</code></div><div class="credential-line"><span>Пароль</span><code>{{ credentials.password }}</code></div><button class="btn secondary w-full mt-5" @click="copy"><Icon :name="copied ? 'Check' : 'Copy'" :size="15" />{{ copied ? 'Скопировано' : 'Скопировать данные' }}</button></div><footer class="modal-footer"><button class="btn primary" @click="credentials = null">Готово<Icon name="Check" :size="16" /></button></footer></Modal>
  <ConfirmDialog v-if="confirmation" :title="confirmation.type === 'reset' ? 'Сбросить пароль?' : 'Удалить преподавателя?'" :message="confirmation.type === 'reset' ? `Для ${confirmation.teacher.name} будет сгенерирован новый пароль. Все активные сессии будут завершены.` : `Аккаунт «${confirmation.teacher.name}», все его материалы и учебные профили будут безвозвратно удалены.`" :action="confirmation.type === 'reset' ? 'Сбросить пароль' : 'Удалить аккаунт'" @close="confirmation = null" @confirm="confirm" />
</template>
<style scoped>
.teacher-access-banner{display:flex;align-items:center;gap:14px;background:linear-gradient(110deg,#f0f8ff,#fbfdff);border:1px solid #dfeefa;border-radius:15px;padding:20px;margin-bottom:30px}.teacher-access-banner>span:first-child{width:41px;height:41px;background:#e4f1fc;border-radius:12px;display:flex;align-items:center;justify-content:center;color:#6aa9d4;flex-shrink:0}.teacher-access-banner strong{font-size:12px;font-weight:500;color:#6589a7}.teacher-access-banner p{font-size:10px;color:#94aabd;margin-top:6px;line-height:1.7}.teacher-access-banner .badge{margin-left:auto}.teachers-table{overflow:hidden}.teacher-table-header{display:grid;grid-template-columns:1fr 170px 200px;gap:15px;background:#f9fbfd;border-bottom:1px solid #edf2f7;padding:13px 21px;color:#a0afbf;font-size:9px}.teacher-table-header>span:last-child{text-align:right}.teacher-row{display:grid;grid-template-columns:1fr 170px 200px;gap:15px;align-items:center;padding:20px 21px;border-bottom:1px solid #edf2f7}.teacher-row:last-child{border:0}.teacher-identity{display:flex;align-items:center;gap:12px;min-width:0}.teacher-identity h3{font-size:12px;overflow-wrap:anywhere}.teacher-identity p{font-size:10px;color:#a3b2c2;margin-top:5px}.teacher-role{width:fit-content}.teacher-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px}.teacher-actions .btn{font-size:10px}.system-account{font-size:9px;color:#b0bccb}.credentials-info{display:flex;gap:12px;padding:15px;border:1px solid #d8efe5;background:#f3fcf7;border-radius:11px;color:#6caf92;margin-bottom:23px}.credentials-info>svg{flex-shrink:0}.credentials-info p{font-size:10px;line-height:1.8}.credential-line{display:grid;gap:8px;margin-top:18px}.credential-line>span{font-size:10px;color:#9cafc0}.credential-line code{padding:12px 14px;background:#f5f9fd;border:1px solid #e6edf5;border-radius:9px;font-size:13px;color:#5a809d;overflow-wrap:anywhere;user-select:all}@media(max-width:1150px){.teacher-table-header,.teacher-row{grid-template-columns:1fr 110px 165px;gap:8px}.teacher-actions{gap:3px}.teacher-actions .btn{padding:7px 8px;font-size:9px}.teacher-role{font-size:8px;padding:4px 6px}}@media(max-width:760px){.teacher-access-banner{padding:15px;gap:11px}.teacher-access-banner .badge{display:none}.teacher-table-header{display:none}.teacher-row{grid-template-columns:1fr auto;padding:16px;gap:15px}.teacher-actions{grid-column:1/-1;justify-content:flex-end;padding-top:12px;border-top:1px solid #f0f4f8}.teacher-role{font-size:8px}.teacher-actions .btn{font-size:10px}.teacher-identity h3{font-size:11px}.teacher-identity{gap:9px}.teacher-identity .avatar{width:32px;height:32px;font-size:10px}}
</style>
